import React from "react";
import "./ProjectCard.css";

const DOT_COLORS = {
  green: "var(--accent2)",
  amber: "var(--accent3)",
  blue:  "var(--accent)",
};

export default function ProjectCard({ title, description, tags, dotColor = "blue" }) {
  return (
    <div className="project-card">
      <div
        className="project-card-dot"
        style={{ background: DOT_COLORS[dotColor] || DOT_COLORS.blue }}
      />
      <div className="project-card-content">
        {title && <h4 className="project-card-title">{title}</h4>}
        <p className="project-card-desc">{description}</p>
        {tags && tags.length > 0 && (
          <div className="project-card-tags">
            {tags.map((tag) => (
              <span key={tag} className="project-tag">{tag}</span>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
